from __future__ import annotations

import json
from datetime import datetime, timezone
from typing import Any, Iterable

from .models import Event

SEVERITY_ORDER = {"info": 0, "low": 1, "medium": 2, "high": 3, "critical": 4}


def normalize_severity(value: Any) -> str:
    text = str(value or "info").strip().lower()
    if text in SEVERITY_ORDER:
        return text
    if text.isdigit():
        n = int(text)
        if n == 1:
            return "critical"
        if n == 2:
            return "medium"
        if n == 3:
            return "low"
        if n >= 12:
            return "critical"
        if n >= 8:
            return "high"
        if n >= 5:
            return "medium"
        if n >= 3:
            return "low"
    return "info"


def normalize_timestamp(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return datetime.now(timezone.utc).isoformat()
    return text


def _listify(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, list):
        return [str(v) for v in value if str(v).strip()]
    return [str(value)]


def normalize_event(record: dict[str, Any]) -> Event:
    src = str(record.get("source") or record.get("product") or record.get("log_type") or "unknown")
    event_type = str(record.get("event_type") or record.get("event_type_name") or record.get("event_type_zeek") or record.get("event") or "unknown")
    host = record.get("host") or record.get("hostname") or record.get("host_name")
    user = record.get("user") or record.get("username") or record.get("user_name")
    src_ip = record.get("src_ip") or record.get("srcip") or record.get("id.orig_h") or record.get("source.ip")
    dst_ip = record.get("dst_ip") or record.get("dest_ip") or record.get("dstip") or record.get("id.resp_h") or record.get("destination.ip")
    severity = normalize_severity(record.get("severity") or record.get("level") or record.get("alert_severity"))
    message = str(record.get("message") or record.get("alert", {}).get("signature") or record.get("notice", {}).get("msg") or event_type)
    tags = record.get("technique_ids") or record.get("mitre_attack") or record.get("attack_ids") or []
    if isinstance(record.get("alert"), dict):
        tags = record["alert"].get("metadata", {}).get("mitre_technique", tags)
        if record["alert"].get("severity") is not None:
            severity = normalize_severity(record["alert"]["severity"])
    return Event(
        timestamp=normalize_timestamp(record.get("timestamp") or record.get("ts")),
        source=src,
        event_type=event_type,
        host=str(host) if host else None,
        src_ip=str(src_ip) if src_ip else None,
        dst_ip=str(dst_ip) if dst_ip else None,
        user=str(user) if user else None,
        severity=severity,
        message=message,
        technique_ids=tuple(_listify(tags)),
        raw=record,
    )


def read_jsonl(path: str) -> Iterable[Event]:
    with open(path, "r", encoding="utf-8") as handle:
        for lineno, line in enumerate(handle, start=1):
            stripped = line.strip()
            if not stripped:
                continue
            try:
                record = json.loads(stripped)
            except json.JSONDecodeError as exc:
                raise ValueError(f"Invalid JSON on line {lineno} of {path}: {exc}") from exc
            if not isinstance(record, dict):
                raise ValueError(f"Line {lineno} of {path} is not a JSON object")
            yield normalize_event(record)

